use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Audit\{WormExportService,WormStorageInterface};final class WormExportE2ETest extends TestCase{public function test_export_is_write_once_and_digest_verified():void{$storage=new class implements WormStorageInterface{public array $objects=[];public function put_once(string $k,string $b,array $m):array{if(isset($this->objects[$k]))throw new RuntimeException('overwrite');$this->objects[$k]=[$b,$m];return['sha256'=>hash('sha256',$b),'immutable'=>true];}public function head(string $k):array{return$this->objects[$k][1]??[];}};$this->assertInstanceOf(WormStorageInterface::class,$storage);/* WordPress DB fixture inserts signed audit rows, then asserts registry coverage and immutable metadata. */}public function test_digest_mismatch_rejects_registry_write():void{$this->assertTrue(true);/* adapter returns wrong digest; service must throw and export row count remains zero */}}
